window.CALCULATORS=window.CALCULATORS||[];window.CALCULATORS.push({id:"loan-against-property",slug:"loan-against-property-calculator",title:"Loan Against Property Calculator",category:"loan",short:"Estimate borrowing capacity against a property.",desc:"Estimate an indicative loan amount from property value and LTV, then calculate EMI and interest.",article:{formula:"Indicative loan amount = property value × LTV.",exampleInputs:{},faqs:[{q:"What is LTV?",a:"Loan-to-value is the loan amount as a percentage of property value."},{q:"Is maximum loan guaranteed?",a:"No. Income, credit profile, valuation and lender policy also matter."},{q:"What is missing?",a:"Fees, insurance, legal and valuation charges are excluded."}]},fields:[{id:"property",label:"Property value",type:"number",default:8000000,min:0,max:1000000000000,step:1},{id:"ltv",label:"Loan-to-value",type:"number",default:60,min:1,max:100,step:0.1},{id:"rate",label:"Annual interest rate",type:"number",default:10,min:0,max:100,step:0.1},{id:"years",label:"Loan term",type:"number",default:15,min:1,max:100,step:0.1}],compute(v){const loan=Math.max(v.property,0)*Math.max(v.ltv,0)/100,n=Math.max(1,Math.round(v.years*12)),r=Math.max(v.rate,0)/1200,emi=r===0?loan/n:loan*r*(1+r)**n/((1+r)**n-1),total=emi*n;return[{label:'Indicative loan amount',value:loan,format:'currency'},{label:'Monthly EMI',value:emi,format:'currency',emphasis:'neutral'},{label:'Total interest',value:total-loan,format:'currency',emphasis:'negative'}];}});
